def transform(grid):
    h, w = len(grid), len(grid[0])
    floor = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    if floor is None:
        floor = next((r for r in range(h) if all(grid[r][c] == 2 for c in range(w))), h - 1)
    direction = 1 if floor == 0 else -1

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            objects.append((color, cells))

    objects.sort(key=lambda obj: min(r for r, c in obj[1]) if direction == 1 else -max(r for r, c in obj[1]))
    out = [[0] * w for _ in range(h)]
    for c in range(w):
        if grid[floor][c] == 2:
            out[floor][c] = 2
    occupied = {(floor, c) for c in range(w)}

    for color, cells in objects:
        dr = 0
        while True:
            nr_cells = [(r + dr + direction, c) for r, c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w or (r, c) in occupied for r, c in nr_cells):
                break
            dr += direction
        for r, c in cells:
            rr = r + dr
            out[rr][c] = color
            occupied.add((rr, c))
    return out
